// YouTube 動画 → 「作品 w のカバーか？誰の？」の判定。docs/01 §5.2。
// 2 つの層を分けて扱う:
//   Art Track（"Provided to YouTube by …" / "Auto-generated by YouTube."）
//     = 商業リリースされた録音。説明欄に Composer / Lyricist が構造化されて載るので、
//       クレジット照合で「同名異曲」を確実に弾ける。プロ層の証拠。
//   一般投稿（歌ってみた・弾き語り・cover）
//     = 民の伝承層の証拠。タイトルのキーワードとチャンネルで判定し、AI 歌声・カラオケ・反応動画などを除外。

import type { ArtistKind, Work } from '../types.ts';
import type { Identity } from '../identity.ts';

export interface YtVideo {
  id: string;
  title: string;
  description: string;
  channelId: string;
  channelTitle: string;
  publishedAt: string; // ISO 8601
  viewCount?: number;
  channelSubscribers?: number;
}

export interface ArtTrack {
  title: string;
  artists: string[];
  releasedOn?: string;
  composers: string[];
  lyricists: string[];
  label?: string;
}

export type Decision =
  | { kind: 'cover'; layer: 'art-track' | 'ugc'; artist: string; artistKind: ArtistKind; year?: number; aiSuspect: boolean }
  | { kind: 'reject'; reason: string };

const MIDDOT = /\s+[·・]\s+/;

export function parseArtTrack(description: string): ArtTrack | null {
  if (!/Auto-generated by YouTube\./.test(description) || !/Provided to YouTube by/.test(description)) return null;
  const lines = description.split(/\r?\n/).map((l) => l.trim());
  const label = lines.find((l) => l.startsWith('Provided to YouTube by'))?.replace('Provided to YouTube by', '').trim();
  const titleLine = lines.find((l) => MIDDOT.test(l));
  if (!titleLine) return null;
  const [title, ...artists] = titleLine.split(MIDDOT).map((s) => s.trim());
  const composers: string[] = [];
  const lyricists: string[] = [];
  for (const l of lines) {
    const m = l.match(/^([A-Za-z ,]+):\s*(.+)$/);
    if (!m) continue;
    const roles = m[1].toLowerCase();
    const names = m[2].split(/\s*[,、／/]\s*/).filter(Boolean);
    if (/composer|writer|songwriter/.test(roles)) composers.push(...names);
    if (/lyricist|writer|songwriter/.test(roles)) lyricists.push(...names);
  }
  const releasedOn = lines.find((l) => l.startsWith('Released on:'))?.replace('Released on:', '').trim();
  return { title, artists, releasedOn, composers, lyricists, label };
}

// 照合用の正規化（括弧・記号・空白を落とす）
export function normTitle(s: string): string {
  return s
    .normalize('NFKC')
    .toLowerCase()
    .replace(/[\s「」『』【】\[\]()（）〜~\-‐–—_.,、。!！?？'"“”’・:：/|]/g, '');
}

const RE_COVER = /(cover|カバー|歌ってみた|うたってみた|弾き語り|歌わせて|covered\s*by)/i;
const RE_INSTRUMENTAL =
  /(カラオケ|karaoke|オフボーカル|off\s*vocal|instrumental|インスト|オルゴール|music\s*box|弾いてみた|叩いてみた|吹いてみた|ピアノソロ|piano\s*solo|bgm)/i;
const RE_NOT_PERFORMANCE = /(reaction|リアクション|解説|歌詞付き|lyrics?\b|和訳|nightcore|slowed|sped\s*up|8d\s*audio|メドレー|medley)/i;
const RE_AI = /(ai\s*cover|aiカバー|ai歌唱|ai\s*vocal|ai\s*ver|rvc|so-?vits|diff-?svc|歌声合成ai)/i;

export function cleanChannel(name: string): string {
  return name
    .replace(/\s*-\s*Topic$/i, '')
    .replace(/\s*(official\s*(youtube\s*)?channel|official|channel|チャンネル|ch\.?)$/i, '')
    .trim();
}

const yearOf = (iso?: string) => (iso && /^\d{4}/.test(iso) ? Number(iso.slice(0, 4)) : undefined);

export function classify(work: Work, v: YtVideo, identity: Identity, proSubscribers = 100_000): Decision {
  const creators = [...work.original, ...work.lyricist, ...work.composer];
  const writers = [...work.lyricist, ...work.composer];
  const wt = normTitle(work.title);

  const art = parseArtTrack(v.description);
  if (art) {
    if (!normTitle(art.title).includes(wt)) return { kind: 'reject', reason: 'title-mismatch' };
    // 同名異曲をクレジットで弾く: 作詞・作曲者の誰か 1 人でも一致すれば同一作品とみなす
    const credits = [...art.composers, ...art.lyricists];
    if (credits.length > 0 && !credits.some((c) => writers.some((x) => identity.id(x) === identity.id(c))))
      return { kind: 'reject', reason: 'different-work' };
    const artist = art.artists[0] ?? cleanChannel(v.channelTitle);
    if (identity.isSelf(artist, creators)) return { kind: 'reject', reason: 'self' };
    return { kind: 'cover', layer: 'art-track', artist, artistKind: 'pro', year: yearOf(art.releasedOn), aiSuspect: false };
  }

  const title = v.title.normalize('NFKC');
  if (!normTitle(title).includes(wt)) return { kind: 'reject', reason: 'title-mismatch' };
  // 2 文字以下の汎用タイトル（糸・駅・花…）は原唱者名か作者名が併記されているものだけ採る
  if (wt.length <= 2 && !creators.some((c) => normTitle(v.title + v.description).includes(normTitle(c))))
    return { kind: 'reject', reason: 'ambiguous-title' };
  if (RE_INSTRUMENTAL.test(title)) return { kind: 'reject', reason: 'instrumental' };
  if (RE_NOT_PERFORMANCE.test(title)) return { kind: 'reject', reason: 'not-performance' };
  if (!RE_COVER.test(title)) return { kind: 'reject', reason: 'not-cover' };
  const artist = cleanChannel(v.channelTitle);
  if (identity.isSelf(artist, creators)) return { kind: 'reject', reason: 'self' };
  const aiSuspect = RE_AI.test(title) || RE_AI.test(v.description);
  const artistKind: ArtistKind = (v.channelSubscribers ?? 0) >= proSubscribers ? 'net' : 'amateur';
  return { kind: 'cover', layer: 'ugc', artist, artistKind, year: yearOf(v.publishedAt), aiSuspect };
}
